import {
  GalleryRoot, GalleryGrid, GalleryToolbar,
  GalleryLightbox, useGallery,
} from "@/components/bevelui/gallery";

function SelectionBanner() {
  const { selectedIds, clearSelection } = useGallery();
  if (selectedIds.size === 0) return null;
  return (
    <div className="flex items-center justify-between p-3 bg-primary/10 rounded-lg">
      <span>{selectedIds.size} items selected</span>
      <button onClick={clearSelection}>Clear</button>
    </div>
  );
}

export function MyGallery() {
  return (
    <GalleryRoot items={items} config={{ selectionMode: "multi" }}>
      <GalleryToolbar />
      <SelectionBanner />
      <GalleryGrid />
      <GalleryLightbox />
    </GalleryRoot>
  );
}
